import { describe, expect, it } from "vitest";

import type { ChartTheme } from "@/lib/echarts";

import { buildRadarOption } from "./RadarChart";

const theme: ChartTheme = {
  textColor: "black",
  mutedTextColor: "gray",
  faintTextColor: "silver",
  axisColor: "rule",
  surfaceColor: "white",
  primaryColor: "gold",
  palette: ["gold", "kinpaku", "green", "warning", "danger"],
  tokenColors: {
    "--ks-primary": "gold",
    "--ks-kinpaku": "kinpaku",
    "--ks-success": "green",
    "--ks-danger": "danger",
    "--ks-lacquer": "lacquer",
  },
};

function getSeries(option: ReturnType<typeof buildRadarOption>) {
  return (option.series as Array<{ data?: Array<Record<string, unknown>> }> | undefined)?.[0];
}

describe("buildRadarOption", () => {
  it("builds radar indicators from axis maxima and resolves series colors", () => {
    const option = buildRadarOption(
      [{ label: "Speed", max: 100 }, { label: "Power" }],
      [
        { label: "A", data: [80, 60], color: "var(--ks-primary)" },
        { label: "B", data: [40, 90] },
      ],
      4,
      theme
    );

    expect(option.radar).toEqual(
      expect.objectContaining({
        indicator: [
          { name: "Speed", max: 100 },
          { name: "Power", max: 90 },
        ],
        splitNumber: 4,
      })
    );
    expect(getSeries(option)).toEqual(
      expect.objectContaining({
        data: [
          expect.objectContaining({ name: "A", value: [80, 60], lineStyle: { color: "gold" } }),
          expect.objectContaining({ name: "B", value: [40, 90], lineStyle: { color: "kinpaku" } }),
        ],
        symbol: "circle",
        symbolSize: 6,
        lineStyle: { width: 2, join: "round" },
      })
    );
  });

  it("preserves the primary, kinpaku, success, danger palette order and marker styling", () => {
    const option = buildRadarOption(
      [{ label: "A", max: 100 }],
      [
        { label: "Primary", data: [10] },
        { label: "Kinpaku", data: [20] },
        { label: "Success", data: [30] },
        { label: "Danger", data: [40] },
      ],
      4,
      theme
    );
    const data = getSeries(option)?.data ?? [];

    expect(data).toEqual([
      expect.objectContaining({ itemStyle: { color: "gold", borderColor: theme.surfaceColor, borderWidth: 1.5 } }),
      expect.objectContaining({ itemStyle: { color: "kinpaku", borderColor: theme.surfaceColor, borderWidth: 1.5 } }),
      expect.objectContaining({ itemStyle: { color: "green", borderColor: theme.surfaceColor, borderWidth: 1.5 } }),
      expect.objectContaining({ itemStyle: { color: "danger", borderColor: theme.surfaceColor, borderWidth: 1.5 } }),
    ]);
  });

  it("uses zero for missing axis values and preserves configured series colors", () => {
    const option = buildRadarOption(
      [{ label: "A" }, { label: "B", max: 10 }],
      [{ label: "Team", data: [3], color: "#123456" }],
      3,
      theme
    );

    expect(option.radar).toEqual(
      expect.objectContaining({
        indicator: [
          { name: "A", max: 3 },
          { name: "B", max: 10 },
        ],
      })
    );
    expect(getSeries(option)?.data).toEqual([
      expect.objectContaining({
        value: [3, 0],
        itemStyle: { color: "#123456", borderColor: theme.surfaceColor, borderWidth: 1.5 },
      }),
    ]);
  });
});

import type React from 'react'

export interface RadarAxis {
  label: string
  max?: number
}

export interface RadarSeries {
  label: string
  data: number[]
  color?: string
}

export interface RadarChartProps {
  axes: RadarAxis[]
  series: RadarSeries[]
  size?: number
  levels?: number
  showLegend?: boolean
  className?: string
  style?: React.CSSProperties
}

"use client";

import type { EChartsOption } from "echarts";
import { RadarChart as EChartsRadarChart } from "echarts/charts";
import { RadarComponent } from "echarts/components";
import { use as useECharts } from "echarts/core";

import { EChartsContainer, resolveChartColor, resolveChartTheme, type ChartTheme } from "@/lib/echarts";
import { cn } from "@/lib/utils";

import type { RadarAxis, RadarChartProps, RadarSeries } from "./radar-chart.types";

// ECharts registration is global and idempotent; keep the chart module set local.
// eslint-disable-next-line react-hooks/rules-of-hooks
useECharts([EChartsRadarChart, RadarComponent]);

const COLORS = ["var(--ks-primary)", "var(--ks-kinpaku)", "var(--ks-success)", "var(--ks-danger)"];

export function buildRadarOption(
  axes: RadarAxis[],
  series: RadarSeries[],
  levels: number,
  theme: ChartTheme
): EChartsOption {
  const indicator = axes.map((axis, index) => ({
    name: axis.label,
    max: axis.max ?? Math.max(...series.map((item) => item.data[index] ?? 0), 1),
  }));
  return {
    animation: true,
    radar: {
      indicator,
      splitNumber: levels,
      center: ["50%", "50%"] as [string, string],
      radius: "68%",
      axisName: { color: theme.faintTextColor, fontSize: 10 },
      axisLine: { lineStyle: { color: theme.axisColor } },
      splitLine: { lineStyle: { color: theme.axisColor } },
    },
    series: [
      {
        type: "radar",
        symbol: "circle",
        symbolSize: 6,
        lineStyle: { width: 2, join: "round" },
        data: series.map((item, index) => {
          const color = resolveChartColor(item.color ?? COLORS[index % COLORS.length], theme.tokenColors);
          return {
            name: item.label,
            value: axes.map((_, axisIndex) => item.data[axisIndex] ?? 0),
            lineStyle: { color },
            areaStyle: { color, opacity: 0.15 },
            itemStyle: { color, borderColor: theme.surfaceColor, borderWidth: 1.5 },
          };
        }),
      },
    ],
  };
}

export function RadarChart({
  axes,
  series,
  size = 240,
  levels = 4,
  showLegend = true,
  className,
  style,
}: RadarChartProps) {
  const option = buildRadarOption(axes, series, levels, resolveChartTheme());
  return (
    <div className={cn("flex flex-col items-center gap-(--spacing-md)", className)} style={style}>
      <EChartsContainer
        option={option}
        width={size}
        height={size}
        ariaLabel={`Radar chart: ${series.map((item) => item.label).join(", ")}`}
      />
      {showLegend && series.length > 1 && (
        <div className="flex flex-wrap gap-x-(--spacing-lg) gap-y-(--spacing-2xs) justify-center">
          {series.map((item, index) => (
            <div key={item.label} className="flex items-center gap-(--spacing-xs)">
              <div
                suppressHydrationWarning
                className="w-2.5 h-2.5 rounded-full"
                style={{ background: item.color ?? COLORS[index % COLORS.length] }}
              />
              <span className="text-body-caption text-muted">{item.label}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
